import { describe, expect, it } from 'vitest';

import fixture from './foldScene.fixture.json';
import {
  apply,
  normalOf,
  worldMatrices,
  type FoldPanel,
} from './kinematics';

/**
 * The fixture is generated by the Go engine
 * (internal/fold/fixture_test.go): every panel's flat polygon and where
 * the engine puts it at t = 1. This test folds the same tree in
 * TypeScript and compares the vertices, which is how the viewer's matrix
 * composition is held to the engine that produced the geometry.
 */
const foldedAt = fixture.folded_at;

/** The fixture's panels as the kinematics expects them. */
const panels: FoldPanel[] = fixture.panels.map((panel) => ({
  id: panel.id,
  parent: panel.parent,
  hinge: panel.hinge,
  t_start: panel.t_start,
  t_end: panel.t_end,
}));

describe('the viewer kinematics match the Go engine', () => {
  it('places every panel vertex where the engine placed it', () => {
    const matrices = worldMatrices(panels, foldedAt);

    for (const panel of fixture.panels) {
      const matrix = matrices.get(panel.id);
      expect(matrix, panel.id).toBeDefined();
      if (!matrix) {
        continue;
      }

      expect(panel.polygon.length).toBe(panel.folded.length);
      panel.polygon.forEach((point, index) => {
        const actual = apply(matrix, { x: point.x, y: point.y, z: 0 });
        const want = panel.folded[index];
        expect(actual.x, `${panel.id}[${index}].x`).toBeCloseTo(want.x, 6);
        expect(actual.y, `${panel.id}[${index}].y`).toBeCloseTo(want.y, 6);
        expect(actual.z, `${panel.id}[${index}].z`).toBeCloseTo(0, 6);
      });
    }
  });

  it('leaves the front panel exactly where the sheet had it', () => {
    const matrices = worldMatrices(panels, foldedAt);
    const front = fixture.panels.find((panel) => panel.parent === '');
    expect(front).toBeDefined();
    if (!front) {
      return;
    }

    const matrix = matrices.get(front.id);
    expect(matrix).toBeDefined();
    if (!matrix) {
      return;
    }
    front.polygon.forEach((point) => {
      const actual = apply(matrix, { x: point.x, y: point.y, z: 0 });
      expect(actual.x).toBeCloseTo(point.x, 9);
      expect(actual.y).toBeCloseTo(point.y, 9);
    });
  });

  it('turns every flap away from the front', () => {
    const matrices = worldMatrices(panels, foldedAt);
    for (const panel of fixture.panels) {
      if (!panel.parent) {
        continue;
      }
      const matrix = matrices.get(panel.id);
      expect(matrix).toBeDefined();
      if (!matrix) {
        continue;
      }
      // A flap flips once; a corner tuck is carried by its flap and
      // flips twice, so it faces the same way as the front again.
      const expected = panel.id.startsWith('tuck') ? 1 : -1;
      expect(normalOf(matrix).z, panel.id).toBeCloseTo(expected, 9);
    }
  });
});
